// Окно 390×844 (сценарий тикета — телефон; веб-проверка r9 на 390).
export async function phone(page: Page, width = 390, height = 844) {
  await page.setViewportSize({ width, height });
}

// /matches → строка партнёра → чат открыт (поле «כתוב הודעה»).
export async function openChat(page: Page, partner: string) {
  await page.goto('/matches');
  await page.getByText(partner, { exact: true }).last().click();
  await page.waitForURL(/\/chat\//);
  await expect(page.getByRole('textbox', { name: 'כתוב הודעה' })).toBeVisible();
}

// Визуальный порядок символов: «!» в конце латинской фразы должен стоять справа от «Hi» (не улетать влево).
// Возвращает x-координаты букв «H» и «!» внутри текстового узла с этой фразой.
export async function bangAfterHi(loc: Locator, phrase: string) {
  return loc.evaluate((el, phrase) => {
    const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
    let node: Text | null = null;
    while (walker.nextNode()) {
      const t = walker.currentNode as Text;
      if (t.data.includes(phrase)) { node = t; break; }
    }
    if (!node) return null;
    const i = node.data.indexOf(phrase) + phrase.length - 3; // «H» в «Hi!»
    const rect = (start: number) => {
      const r = document.createRange();
      r.setStart(node!, start);
      r.setEnd(node!, start + 1);
      const b = r.getBoundingClientRect();
      return { left: b.left, right: b.right };
    };
    return { h: rect(i), bang: rect(i + 2) };
  }, phrase);
}

export async function expectBangAtEnd(loc: Locator, phrase: string) {
  const pos = await bangAfterHi(loc, phrase);
  expect(pos, `текст «${phrase}» найден на экране`).not.toBeNull();
  expect(pos!.bang.left, '«!» стоит справа от «Hi» (в конце фразы)').toBeGreaterThanOrEqual(pos!.h.right - 1);
}
